const jobs = $input.first().json.data || [];

return jobs.map(job => {
  const cleanDesc = (job.description || '').replace(/<[^>]*>?/gm, ' ').replace(/\s+/g, ' ').trim().slice(0, 6000);
  return {
    json: {
      source: 'arbeitnow',
      id: job.slug,
      title: job.title,
      company: job.company_name,
      url: job.url,
      location_raw: (job.locations || []).join(', '),
      work_policy: job.remote ? 'remote' : 'onsite',
      posted_date: new Date(job.created_at * 1000).toISOString(), // Convert timestamp
      description_text: cleanDesc,
      visa_sponsorship: job.visa_sponsorship === true
    }
  };
});

// Job Radar v2 | RemoteOK Mapper1 (v1 node, patched). Input: "RemoteOK".
// Fix (run 1, 2026-10-30): the map read job.description on the n8n item wrapper, so every description
// was empty and the length filter dropped all jobs (100 in, 0 out). It now reads item.json.
const items = $input.all();

// Hard veto: drop legal disclaimer, missing fields, string "undefined", and whitespace/empty descriptions
const jobs = items.filter(item => {
  const j = item.json;
  if (!j || !j.position || !j.company) return false;

  // Guard 1: reject literal string "undefined" and whitespace-only IDs
  const id = String(j.id || '').trim();
  if (!id || id.toLowerCase() === 'undefined') return false;

  // Guard 2: reject whitespace-only or HTML-comment-only descriptions (before regex cleaning)
  const desc = String(j.description || '').trim();
  if (desc.length < 50) return false;

  return true;
});

return jobs.map(item => {
  const job = item.json;
  const cleanDesc = (job.description || '').replace(/<[^>]*>?/gm, ' ').replace(/\s+/g, ' ').trim().slice(0, 6000);
  let finalUrl = job.url;
  if (finalUrl && !finalUrl.startsWith('http')) finalUrl = 'https://remoteok.com' + finalUrl;

  return {
    json: {
      source: 'remoteok',
      id: String(job.id).trim(),
      title: job.position,
      company: job.company,
      url: finalUrl,
      location_raw: job.location || 'Worldwide',
      work_policy: 'remote',
      posted_date: job.date,
      description_text: cleanDesc,
      visa_sponsorship: false,
      heuristic_score: 0
    }
  };
}).filter(item => item.json.description_text.length > 100);

const jobs = $input.first().json.jobs || [];
const htmlRegex = /<[^>]*>?/gm; // Regex to strip HTML tags

return jobs.map(job => {
  const cleanDesc = (job.description || '').replace(htmlRegex, ' ').replace(/\s+/g, ' ').trim().slice(0, 6000);
  return {
    json: {
      source: 'remotive',
      id: String(job.id),
      title: job.title,
      company: job.company_name,
      url: job.url,
      location_raw: job.candidate_required_location || 'Worldwide',
      work_policy: 'remote', 
      posted_date: job.publication_date,
      description_text: cleanDesc,
      visa_sponsorship: false 
    }
  };
});

// Job Radar v2 | Build Prompts (Code, run once for all items). Input: "Rank & Slice".
// The candidate profile now lives in config.profile (edited in the console), not in this code.
const L = $('Load Config').first().json;
const C = L.config;
const items = $input.all().map(i => i.json).filter(j => j.url);
if (!items.length) return [{ json: { __empty: true } }];

const SYSTEM = [
  'You are a strict job-fit analyst for one candidate. Evaluate ONE posting against the candidate profile.',
  'Return ONLY valid JSON with exactly this schema:',
  '{"match_score": number 0-100, "why_match": string (max 2 sentences), "red_flags": [string], "confidence": number 0-100,',
  ' "extracted": {"job_title": string, "company": string,',
  '  "seniority": "intern|entry|junior|mid|senior|lead|unknown",',
  '  "min_years_required": number or null (the smallest MINIMUM years of experience the posting REQUIRES; null if none is stated; months as a fraction),',
  '  "experience_evidence": string (quote the exact phrase, or ""),',
  '  "work_mode": "remote|hybrid|onsite|unknown", "location_constraint": string,',
  '  "remote_region": "worldwide|emea|europe|us|americas|apac|uk|country|unknown",',
  '  "languages_required": [string] (only languages that are REQUIRED, never "nice to have"),',
  '  "visa_status": "sponsors|relocation_support|no_sponsorship|work_auth_required|unknown",',
  '  "employment_type": "full_time|part_time|contract|freelance|internship|unknown",',
  '  "contract_friendly": boolean, "company_size_hint": string, "salary": string}}',
  'Rules: never guess years; "proven experience" without a number means null. A freelance gig is judged on the task, not on employer perks.'
].join('\n');

const profile = JSON.stringify(C.profile);
const maxChars = Number(C.llm.max_desc_chars) || 3500;
return items.map(j => ({ json: {
  system: SYSTEM,
  prompt: 'Candidate profile: ' + profile +
    '\n\nPosting (' + j.kind + ', source ' + j.source + ')\nTitle: ' + j.title + '\nCompany: ' + j.company +
    '\nLocation: ' + (j.location_raw || 'not stated') + '\nWork mode (detected): ' + j.work_mode +
    '\nDescription: ' + String(j.description_text || '').slice(0, maxChars) +
    '\n\nEvaluate fit and extract attributes. JSON only.',
  job: j
} }));

// Job Radar v2 | LLM Router v7 (Code, run once for all items). Input: "Build Prompts".
// v6 chain unchanged (groq gpt-oss-120b -> gemini 3.5 flash-lite -> gemini 2.5 flash). v7 adds:
//  - skips the {__empty} sentinel (no LLM call when nothing survived the gates)
//  - pacing from config llm.pace_ms (Groq free tier: 8K tokens/min and about 1.8K tokens per call, so 15 s)
//  - a time budget under N8N_RUNNERS_TASK_TIMEOUT: items it cannot reach are returned with
//    provider "deferred" and go back to the queue (skipped_cap) instead of killing the run
const GROQ_URL = 'https://api.groq.com/openai/v1/chat/completions';
const GEMINI_URL = 'https://generativelanguage.googleapis.com/v1beta/openai/chat/completions';
const CHAIN = [
  { name: 'groq-gptoss',      url: GROQ_URL,   key: () => $env.GROQ_API_KEY,   model: 'openai/gpt-oss-120b' },
  { name: 'gemini-3.5-lite',  url: GEMINI_URL, key: () => $env.GEMINI_API_KEY, model: 'gemini-3.5-flash-lite', temperature: 0.2 },
  { name: 'gemini-2.5-flash', url: GEMINI_URL, key: () => $env.GEMINI_API_KEY, model: 'gemini-2.5-flash', temperature: 0.2 }
];
const C = $('Load Config').first().json.config;
const PACE = Math.max(4000, Number(C.llm.pace_ms) || 15000);
let limitS = 280;
try { limitS = Math.max(120, (Number($env.N8N_RUNNERS_TASK_TIMEOUT) || 300) - 30); } catch (e) { /* default */ }
const started = Date.now();
const sleep = ms => new Promise(r => setTimeout(r, ms));
function parseJSON(s) {
  try { return JSON.parse(s); } catch (e) {
    const m = (s || '').match(/\{[\s\S]*\}/);
    try { return m ? JSON.parse(m[0]) : null; } catch (e2) { return null; }
  }
}
const callProvider = async (p, system, prompt) => {
  const body = { model: p.model, messages: [{ role: 'system', content: system }, { role: 'user', content: prompt }] };
  if (typeof p.temperature === 'number') body.temperature = p.temperature;
  const data = await this.helpers.httpRequest({
    method: 'POST', url: p.url, timeout: 60000,
    headers: { 'Authorization': 'Bearer ' + p.key(), 'Content-Type': 'application/json' }, body, json: true
  });
  if (data.error) throw new Error(data.error.message || JSON.stringify(data.error));
  const parsed = parseJSON(data.choices?.[0]?.message?.content || '');
  if (!parsed) throw new Error('Unparseable JSON');
  return parsed;
};
const is429 = e => /429|rate|resource has been exhausted/i.test(String(e.message || e));

const items = $input.all().filter(i => i.json && i.json.prompt);
if (!items.length) return [{ json: { __empty: true } }];
const results = [];
for (let i = 0; i < items.length; i++) {
  const { system, prompt, job } = items[i].json;
  if ((Date.now() - started) / 1000 > limitS - 70) { results.push({ json: { job, provider: 'deferred', llm: null, errors: { budget: 'task time budget reached' } } }); continue; }
  let llm = null, provider = 'none';
  const errors = {};
  for (const p of CHAIN) {
    for (let attempt = 0; attempt < 2; attempt++) {
      try { llm = await callProvider(p, system, prompt); provider = p.name; break; }
      catch (e) {
        errors[p.name] = String(e.message || e).slice(0, 200);
        if (is429(e) && attempt === 0 && (Date.now() - started) / 1000 < limitS - 90) { await sleep(25000); continue; }
        break;
      }
    }
    if (llm) break;
  }
  results.push({ json: { job, provider, llm, errors } });
  if (i < items.length - 1) await sleep(PACE);
}
return results;

// Job Radar v2 | Gate & Score v2 (Code, run once for all items). Input: "LLM Router".
// Gate C re-checks the hard rules on what the LLM extracted (it reads phrasings the regexes miss),
// then scores. Emits one result per job: outcome matched | below_score | dropped_llm | llm_failed | deferred.
const L = $('Load Config').first().json;
const C = L.config;
const W = Object.assign({ match: 0.40, filterFit: 0.25, feasibility: 0.20, recency: 0.15 }, C.scoring.weights);
const maxYears = Number(C.experience.max_years_required) || 0;
const seniorityOk = new Set((C.experience.seniority_ok || []).map(s => String(s).toLowerCase()));
const blockedLang = (C.languages.blocked || []).map(s => s.toLowerCase());
const BAD_REGIONS = new Set(['us', 'americas', 'apac', 'uk']);
const WIDE = new Set(['worldwide', 'emea', 'europe']);
const clamp = n => Math.max(0, Math.min(100, Number(n) || 0));

const out = [];
for (const item of $input.all()) {
  const { job, provider, llm } = item.json;
  if (!job || !job.url) continue;
  const base = { posting_id: job.posting_id, url: job.url, source: job.source };
  if (provider === 'deferred') { out.push({ json: Object.assign(base, { outcome: 'deferred', reason: 'llm_time_budget' }) }); continue; }
  if (!llm) { out.push({ json: Object.assign(base, { outcome: 'llm_failed', reason: 'all_providers_failed', detail: JSON.stringify(item.json.errors || {}).slice(0, 200) }) }); continue; }

  const ex = llm.extracted || {};
  const seniority = String(ex.seniority || 'unknown').toLowerCase();
  const mode = ['remote', 'hybrid', 'onsite'].includes(String(ex.work_mode).toLowerCase()) ? String(ex.work_mode).toLowerCase()
    : (['remote', 'hybrid', 'onsite'].includes(job.work_mode) ? job.work_mode : 'unknown');
  const region = String(ex.remote_region || 'unknown').toLowerCase();
  const visa = String(ex.visa_status || 'unknown').toLowerCase();
  const langs = (Array.isArray(ex.languages_required) ? ex.languages_required : []).map(l => String(l).toLowerCase());
  const years = (ex.min_years_required === null || ex.min_years_required === undefined || ex.min_years_required === '') ? null : Number(ex.min_years_required);
  const contract = !!ex.contract_friendly;
  const wm = C.work_modes;

  let drop = null;
  if (Number.isFinite(years) && years >= maxYears + 1) drop = ['llm_experience', String(ex.experience_evidence || years + ' years').slice(0, 200)];
  else if (!seniorityOk.has(seniority)) drop = ['llm_seniority', seniority];
  else if (langs.some(l => blockedLang.some(b => l.includes(b)))) drop = ['llm_language', langs.join(', ')];
  else if (mode !== 'unknown' && !wm[mode].enabled) drop = ['llm_work_mode', mode];
  else if (mode === 'remote' && (visa === 'work_auth_required' || (BAD_REGIONS.has(region) && !contract))) drop = ['llm_location', region + ' / ' + visa];
  else if ((mode === 'hybrid' || mode === 'onsite') && wm[mode].require_visa) {
    if (visa === 'no_sponsorship' || visa === 'work_auth_required') drop = ['llm_visa', visa];
    else if (visa === 'unknown' && job.visa_signal !== 'positive' && C.visa.unknown_policy === 'drop') drop = ['llm_visa', 'unknown'];
  }
  if (drop) { out.push({ json: Object.assign(base, { outcome: 'dropped_llm', reason: drop[0], detail: drop[1] }) }); continue; }

  // ---- score (same four factors as v1; feasibility now reads visa_status and remote region) ----
  const match = clamp(llm.match_score);
  const juniorish = ['intern', 'entry', 'junior'].includes(seniority);
  const wide = WIDE.has(region);
  const visaOk = visa === 'sponsors' || visa === 'relocation_support' || job.visa_signal === 'positive';
  const filterFit = ((juniorish ? 1 : 0) + (mode === 'remote' ? 1 : 0) + (wide ? 1 : 0) + (visaOk || contract ? 1 : 0)) / 4 * 100;
  const feasibility = mode === 'remote'
    ? (wide ? 75 : region === 'unknown' ? 55 : 35) + (contract ? 10 : 0)
    : (visa === 'sponsors' ? 90 : visa === 'relocation_support' ? 80 : job.visa_signal === 'positive' ? 70 : 30);
  const days = (Date.now() - new Date(job.posted_date).getTime()) / 86400000;
  const recency = days <= 2 ? 100 : days <= 7 ? 80 : days <= 14 ? 60 : 40;
  const final = Math.round(W.match * match + W.filterFit * filterFit + W.feasibility * Math.min(100, feasibility) + W.recency * recency);
  const breakdown = 'match=' + match + '; fit=' + Math.round(filterFit) + '; feas=' + Math.min(100, feasibility) + '; rec=' + recency;
  if (final < C.scoring.min_score) { out.push({ json: Object.assign(base, { outcome: 'below_score', reason: 'below_min_score', final_score: final, detail: breakdown }) }); continue; }

  const CLEAN = new Set(['linkedin', 'ats', 'working-nomads', 'remotive', 'remoteok', 'arbeitnow', 'weworkremotely', 'weworkremotely-mkt', 'jobicy', 'himalayas', 'revopsroles', 'remocate']);
  const cleanTitle = (!CLEAN.has(job.source) || job.title.length > 120 || job.title === '(untitled)') && ex.job_title ? String(ex.job_title) : job.title;
  const company = (job.company === 'unknown' || /^r\//.test(job.company)) && ex.company ? String(ex.company) : job.company;
  out.push({ json: Object.assign(base, {
    outcome: 'matched', final_score: final,
    match: {
      posting_id: job.posting_id, url: job.url, source: job.source, kind: job.kind,
      title: cleanTitle.slice(0, 300), company: company.slice(0, 200), location_raw: job.location_raw,
      work_mode: mode, employment_type: String(ex.employment_type || job.employment_type || 'unknown'),
      posted_date: job.posted_date, final_score: final, priority: final >= C.scoring.priority_score,
      why_match: llm.why_match || '', red_flags: (Array.isArray(llm.red_flags) ? llm.red_flags : []).join('; '),
      seniority, min_years_required: Number.isFinite(years) ? years : (job.regex_min_years ?? ''),
      experience_evidence: String(ex.experience_evidence || job.regex_evidence || '').slice(0, 300),
      languages_required: langs.join(', '), visa_status: visa === 'unknown' && job.visa_signal === 'positive' ? 'signal:' + job.visa_evidence : visa,
      remote_region: region, contract_friendly: contract, company_size_hint: ex.company_size_hint || 'unknown',
      salary: ex.salary || 'not listed', confidence: clamp(llm.confidence), provider, score_breakdown: breakdown
    }
  }) });
}
return out.length ? out : [{ json: { __empty: true } }];

// Job Radar v2 | Run Stats (Code, run once for all items). Input: "Record Postings".
// Builds the jr_finish_run() payload: the funnel for this run and one stats object per source.
const safeAll = name => { try { return $(name).all().map(i => i.json); } catch (e) { return []; } };
const L = $('Load Config').first().json;
const merged = safeAll('Merge All');
const norm = safeAll('Normalize').filter(j => j.url);
const gateA = safeAll('Gate A').filter(j => j.url);
const fresh = safeAll('Rejoin').filter(j => j.url);
const gateB = safeAll('Gate B').filter(j => j.url);
const router = safeAll('LLM Router').filter(j => j.job);
const scored = safeAll('Gate & Score').filter(j => j.url);
const rec = (safeAll('Record Postings')[0] || {}).result || {};

const S = {};
const bump = (src, k, n = 1) => { S[src] = S[src] || { fetched: 0, errors: 0, gate_a_pass: 0, new: 0, gate_b_pass: 0, matches: 0 }; S[src][k] += n; };
for (const j of merged) {
  if (j.__error) { bump(j.source || 'unknown', 'errors'); S[j.source || 'unknown'].error = String(j.__error).slice(0, 200); }
  else if (j.__skip && j.source && j.source !== 'normalize') { bump(j.source, 'fetched', 0); S[j.source].skipped = j.__skip; }
}
for (const j of norm) bump(j.source, 'fetched');
for (const j of gateA) if (j.gate_a === 'pass') bump(j.source, 'gate_a_pass');
for (const j of fresh) bump(j.source, 'new');
for (const j of gateB) if (j.gate_b === 'pass') bump(j.source, 'gate_b_pass');
for (const r of scored) if (r.outcome === 'matched') bump(r.source, 'matches');

const providers = router.map(r => r.provider);
const funnel = {
  merged: merged.length,
  fetched: norm.length,
  gate_a_pass: gateA.filter(j => j.gate_a === 'pass').length,
  new_or_retry: fresh.length,
  detail_ok: gateB.filter(j => j.detail_status === 'ok').length,
  gate_b_pass: gateB.filter(j => j.gate_b === 'pass').length,
  llm_calls: providers.filter(p => p !== 'none' && p !== 'deferred').length,
  llm_deferred: providers.filter(p => p === 'deferred').length,
  scored: scored.length,
  matches: scored.filter(r => r.outcome === 'matched').length,
  matches_new: Number(rec.matches_new || 0)
};
const sourceErrors = merged.filter(j => j.__error).map(j => j.__error);
const routerErrors = router.filter(r => r.errors && Object.keys(r.errors).length).slice(0, 2).map(r => JSON.stringify(r.errors).slice(0, 160));
return [{ json: {
  run_id: L.run_id,
  payload: {
    funnel, source_stats: S,
    providers: providers.join(','),
    failures: providers.filter(p => p === 'none').length,
    warnings: (L.warnings || []).join('; '),
    errors_sample: sourceErrors.concat(routerErrors).join(' | ').slice(0, 1500)
  }
} }];

return $input.all().map(item => {
  const r = item.json;
  return { json: {
    source: 'weworkremotely',
    id: r.guid || r.link,
    title: r.title,
    company: (r.creator || '').trim() || 'unknown',
    url: r.link,
    location_raw: 'Worldwide',
    work_policy: 'remote',
    posted_date: r.isoDate || r.pubDate || new Date().toISOString(),
    description_text: (r.content || r.contentSnippet || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 6000),
    visa_sponsorship: false,
    heuristic_score: 0
  }};
});

const SOURCE = 'n8n-community';
return $input.all().map(item => {
  const r = item.json;
  const title = (r.title || '').trim();
if (/\[for hire\]|available for hire|available for projects|open for projects|looking for clients/i.test(title)) return null; // freelancer pitches, not jobs
  const text = (title + ' ' + (r.content || '')).toLowerCase();
  return { json: {
    source: SOURCE, id: r.guid || r.link, title, company: 'unknown', url: r.link,
    location_raw: 'Worldwide',
    work_policy: /remote|anywhere|worldwide|emea|europe|utc/i.test(text) ? 'remote' : 'unknown',
    posted_date: r.isoDate || r.pubDate || new Date().toISOString(),
    description_text: (r.content || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 6000),
    visa_sponsorship: false, heuristic_score: 0
  }};
}).filter(Boolean);

const jobs = $input.first().json.jobs || [];
return jobs.map(j => ({ json: {
  source: 'jobicy', id: String(j.id), title: j.jobTitle, company: j.companyName || 'unknown',
  url: j.url, location_raw: j.jobGeo || 'Worldwide', work_policy: 'remote',
  posted_date: j.pubDate || new Date().toISOString(),
  description_text: (j.jobDescription || j.jobExcerpt || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 6000),
  visa_sponsorship: false, heuristic_score: 0
}})).filter(x => !/^(americas|north america|usa|us|canada|apac|asia|australia|latam|latin america)$/i.test(x.json.location_raw));

return $input.all().map(item => {
  const r = item.json;
  return { json: {
    source: 'weworkremotely-mkt',
    id: r.guid || r.link,
    title: r.title,
    company: (r.creator || '').trim() || 'unknown',
    url: r.link,
    location_raw: 'Worldwide',
    work_policy: 'remote',
    posted_date: r.isoDate || r.pubDate || new Date().toISOString(),
    description_text: (r.content || r.contentSnippet || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 6000),
    visa_sponsorship: false,
    heuristic_score: 0
  }};
});

// Monthly thread; each top-level comment = one job post. Empty at month start = safe [].
const SOURCE = 'hn-whoishiring';
try {
  const label = new Date().toLocaleString('en-US', { month: 'long', year: 'numeric' });
  const search = await this.helpers.httpRequest({ method: 'GET', json: true,
    url: 'https://hn.algolia.com/api/v1/search?tags=story&query=' + encodeURIComponent('Ask HN: Who is hiring? ' + label) });
  const hits = search.hits || [];
  const story = hits.find(h => (h.title || '').includes(label)) || hits[0]; // prefer exact-month thread
  if (!story) return [];
  const thread = await this.helpers.httpRequest({ method: 'GET', json: true,
    url: 'https://hn.algolia.com/api/v1/items/' + story.objectID });
  return (thread.children || []).filter(c => c.text).slice(0, 40).map(c => {
    const clean = c.text.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
    const href = (c.text.match(/href="([^"]+)"/) || [])[1];
    return { json: {
      source: SOURCE, id: String(c.id), title: clean.slice(0, 120), company: 'unknown',
      url: href || ('https://news.ycombinator.com/item?id=' + c.id),
      location_raw: 'Worldwide',
      work_policy: /remote|anywhere|worldwide/i.test(clean) ? 'remote' : 'unknown',
      posted_date: c.created_at || story.created_at || new Date().toISOString(),
      description_text: clean.slice(0, 6000), visa_sponsorship: false, heuristic_score: 0
    }};
  });
} catch (e) {
  // Never kill the run: marker item (no url) is dropped by Dedupe but counted in ops
  return [{ json: { source: SOURCE, id: 'error', title: '', company: '', url: '',
    location_raw: '', work_policy: 'unknown', posted_date: new Date().toISOString(),
    description_text: '', visa_sponsorship: false, heuristic_score: 0,
    __error: SOURCE + ': ' + String(e.message || e) } }];
}

// Himalayas — free public JSON API, no key. Queries come from the config tab.
const SOURCE = 'himalayas';
let QUERIES = [];
try {
  const cfgQ = $('Load Config').first().json.config.himalayas_queries;
  QUERIES = Array.isArray(cfgQ) ? cfgQ.map(q => (typeof q === 'string' ? q : q.q)).filter(Boolean) : [];
} catch (e) { QUERIES = []; }
if (!QUERIES.length) QUERIES = ['automation engineer', 'integration engineer', 'revenue operations'];

const seenGuids = new Set();
const out = [];
try {
  for (const q of QUERIES) {
    const res = await this.helpers.httpRequest({ method: 'GET', json: true,
      url: 'https://himalayas.app/jobs/api/search?q=' + encodeURIComponent(q) + '&sort=recent&page=1' });
    for (const j of (res.jobs || [])) {
      if (seenGuids.has(j.guid)) continue;
      seenGuids.add(j.guid);
      const loc = (j.locationRestrictions || []).map(l => l.name).join(', ');
      const posted = j.pubDate ? (j.pubDate > 1e12 ? new Date(j.pubDate) : new Date(j.pubDate * 1000)) : new Date();
      out.push({ json: {
        source: SOURCE, id: j.guid, title: j.title, company: j.companyName || 'unknown',
        url: j.applicationLink || ('https://himalayas.app/jobs/' + (j.companySlug || '')),
        location_raw: loc || 'Worldwide',
        work_policy: 'remote',
        posted_date: posted.toISOString(),
        description_text: (j.description || j.excerpt || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 6000),
        visa_sponsorship: false, heuristic_score: 0
      }});
    }
  }
  return out;
} catch (e) {
  return out.length ? out : [{ json: { source: SOURCE, id: 'error', title: '', company: '', url: '',
    location_raw: '', work_policy: 'unknown', posted_date: new Date().toISOString(),
    description_text: '', visa_sponsorship: false, heuristic_score: 0,
    __error: SOURCE + ': ' + String(e.message || e) } }];
}

// Job Radar v2 | Load Config (Code, run once for all items)
// Input: "Start Run" -> { ctx: jr_start_run() result }. The config was validated by jr_validate_config()
// when it was saved, so this node only fills safe fallbacks, computes source cadence, and keeps the
// legacy keys the v1 source nodes still read (himalayas_queries, remocate_*, window_days).
const raw = $('Start Run').first().json.ctx;
const ctx = typeof raw === 'string' ? JSON.parse(raw) : (raw || {});
if (!ctx.run_id || !ctx.config) throw new Error('Start Run returned no run_id/config: is the schema applied?');

const warnings = [];
const cfg = ctx.config;
const num = (v, fb, key) => { const n = Number(v); if (!Number.isFinite(n)) { warnings.push(key + ':fallback'); return fb; } return n; };

cfg.freshness = cfg.freshness || {};
cfg.freshness.window_days = num(cfg.freshness.window_days, 7, 'freshness.window_days');
cfg.llm = Object.assign({ slice_cap: 40, detail_cap: 40, max_per_source: 12, pace_ms: 15000, max_desc_chars: 3500 }, cfg.llm || {});
cfg.scoring = cfg.scoring || {};
cfg.scoring.weights = Object.assign({ match: 0.4, filterFit: 0.25, feasibility: 0.2, recency: 0.15 }, cfg.scoring.weights || {});
cfg.sources = cfg.sources || {};

// Cadence: weekly sources run when they have not fetched anything for 6 days.
const lastOk = ctx.last_ok || {};
const due = {};
const isDue = (key, cadence) => {
  if (cadence !== 'weekly') return true;
  const t = lastOk[key] ? new Date(lastOk[key]).getTime() : 0;
  return !t || (Date.now() - t) > 6 * 86400000;
};
for (const [key, s] of Object.entries(cfg.sources)) {
  if (key === 'boards') continue;
  due[key] = !!(s && s.enabled) && isDue(key, s && s.cadence);
}
for (const b of (cfg.sources.boards || [])) due[b.key] = !!b.enabled && isDue(b.key, b.cadence);

// Legacy aliases read by unchanged v1 nodes (Himalayas1, Remocate Mapper).
const S = cfg.sources;
const config = Object.assign({}, cfg, {
  window_days: cfg.freshness.window_days,
  himalayas_queries: (S.himalayas && S.himalayas.queries) || [],
  remocate_enabled: !!(S.remocate && S.remocate.enabled),
  remocate_categories: (S.remocate && S.remocate.categories) || ['sales', 'marketing', 'analytics', 'manager'],
  revops_enabled: !!(S.revopsroles && S.revopsroles.enabled),
  arbeitnow_visa_only: !!(S.arbeitnow && S.arbeitnow.visa_only)
});

return [{ json: {
  run_id: Number(ctx.run_id), rev: ctx.rev, trigger: ctx.trigger, started_at: ctx.started_at,
  config, due, warnings
} }];

const CFG = $('Load Config').first().json.config;
if (CFG.revops_enabled === false) return [];                // config kill-switch
const cutoff = Date.now() - CFG.window_days * 86400000;
const cats = new Set(CFG.revops_categories || []);
// Structured deterministic vetoes — free, pre-slice, from the API's own classified fields
const SENIORITY_VETO = ['senior', 'manager', 'vp', 'director', 'c-level'];
const FLAG_VETO = ['quota-carrying', 'commission-based'];
const MAX_EXP_MIN = 4;                                      // 4+ yrs required ≠ entry/junior profile
const seenIds = new Set();
const out = [];
for (const item of $input.all()) {
  for (const j of ((item.json && item.json.hits) || [])) {
    if (!j || !j.id || !j.title || seenIds.has(j.id)) continue;
    seenIds.add(j.id);
    if (j.is_sponsored) continue;                            // paid placement, not organic
    const posted = Number(j.posted_at) || 0;
    const postedMs = posted > 1e12 ? posted : posted * 1000; // epoch seconds vs ms quirk
    if (!postedMs || postedMs < cutoff) continue;            // window filter, client-side
    if (j.work_mode !== 'remote') continue;
    if (cats.size && !cats.has(j.category)) continue;        // ICP categories only
    if (SENIORITY_VETO.includes(String(j.seniority || '').toLowerCase())) continue;
    if ((Number(j.experience_years_min) || 0) >= MAX_EXP_MIN) continue;
    if ((j.red_flags || []).some(f => FLAG_VETO.includes(String(f).toLowerCase()))) continue;
    const salary = (j.salary_min || j.salary_max)
      ? (j.salary_min || '?') + '–' + (j.salary_max || '?') + ' ' + (j.salary_currency || '')
      : 'not listed';
    out.push({ json: {
      source: 'revopsroles',
      id: String(j.id),
      title: j.title,
      company: j.company_name || 'unknown',
      url: j.source_url || ('https://revopsroles.com/jobs/' + j.id),
      location_raw: j.location_raw || 'Worldwide',
      work_policy: 'remote',
      posted_date: new Date(postedMs).toISOString(),
      description_text: [
        'Title: ' + j.title,
        'Company: ' + (j.company_name || 'unknown') + ' (size: ' + (j.company_size || 'unknown') + ', industry: ' + (j.industry || 'unknown') + ')',
        'Category: ' + j.category + ' | Seniority: ' + j.seniority + ' | Experience: ' + (j.experience_years_min || 0) + '-' + (j.experience_years_max || 'n/a') + ' years',
        'Work mode: ' + j.work_mode + ' | Employment type: ' + (j.employment_type || 'unknown') + ' | Location: ' + (j.location_raw || 'unknown'),
        'Tools: ' + ((j.tools || []).join(', ') || 'not listed'),
        'Salary: ' + salary + ' | Comp structure: ' + (j.comp_structure || 'unknown'),
        'Red flags: ' + ((j.red_flags || []).join(', ') || 'none'),
        'Visa sponsorship: ' + (j.visa_sponsorship === true ? 'yes' : j.visa_sponsorship === false ? 'no' : 'unknown'),
        'Uses AI tools: ' + (j.uses_ai_tools === true ? 'yes' : 'unknown')
      ].join('\n').slice(0, 6000),
      visa_sponsorship: j.visa_sponsorship === true,
      heuristic_score: 0
    }});
  }
}
return out;

// Clay Community (Tightknit SPA) via Jina Reader rendered-markdown bridge — ADR-JR-15
const SOURCE = 'clay-community';
const rawIn = $input.first().json;
const md = typeof rawIn.data === 'string' ? rawIn.data : (typeof rawIn.content === 'string' ? rawIn.content : (typeof rawIn.text === 'string' ? rawIn.text : ''));
const errItem = msg => [{ json: { source: SOURCE, id: 'error', title: '', company: '', url: '',
  location_raw: '', work_policy: 'unknown', posted_date: new Date().toISOString(),
  description_text: '', visa_sponsorship: false, heuristic_score: 0, __error: SOURCE + ': ' + msg } }];
if (md.length < 500) return errItem('empty/unsupported reader payload (' + md.length + ' chars)');

const linkRe = /\[([^\]\n]{8,140})\]\((https:\/\/community\.clay\.com\/x\/share-jobs\/[^)\s]+)\)/g;
const seen = new Set(); const posts = []; let m;
while ((m = linkRe.exec(md)) !== null) {
  if (seen.has(m[2])) continue;
  seen.add(m[2]);
  posts.push({ title: m[1].trim(), url: m[2], start: m.index });
}
if (!posts.length) return errItem('no post links parsed — page format changed?');

const now = Date.now();
const ago = chunk => {
  const t = chunk.match(/(\d+)\s*(minute|min|hour|hr|day|week|month)s?\s*ago/i);
  if (!t) return new Date(now).toISOString();
  const n = Number(t[1]); const u = t[2].toLowerCase();
  const mult = u.startsWith('min') ? 60000 : u.startsWith('h') ? 3600000 : u.startsWith('d') ? 86400000 : u.startsWith('w') ? 604800000 : 2592000000;
  return new Date(now - n * mult).toISOString();
};

const out = [];
for (let i = 0; i < posts.length && out.length < 30; i++) {
  const p = posts[i];
  const end = i + 1 < posts.length ? posts[i + 1].start : md.length;
  const chunk = md.slice(p.start, end);
  const body = chunk.replace(/\[([^\]]*)\]\([^)]*\)/g, '$1').replace(/<[^>]*>/g, ' ')
    .replace(/[#>*_`|]+/g, ' ').replace(/\s+/g, ' ').trim();
  const title = p.title.replace(/<[^>]*>/g, '').trim();
  if (/looking for work|hire me|available for hire|open to work|seeking (a )?(new )?role|my services/i.test(title + ' ' + body.slice(0, 300))) continue; // freelancer pitches, not jobs
  out.push({ json: {
    source: SOURCE, id: p.url, title, company: 'unknown', url: p.url,
    location_raw: 'Worldwide',
    work_policy: /remote|worldwide|anywhere|emea|europe/i.test(body) ? 'remote' : 'unknown',
    posted_date: ago(chunk),
    description_text: (title + '. ' + body).slice(0, 6000),
    visa_sponsorship: false, heuristic_score: 0
  }});
}
return out.length ? out : errItem('links found but all vetoed/empty');

// Remocate (Source #12) — Jina Reader bridge over category pages. ADR-JR-16.
// Fetches 4 category pages, parses inline JDs using date anchors. 4 requests/run.
const CFG = $('Load Config').first().json.config;
if (CFG.remocate_enabled === false) return [];

const CATS = CFG.remocate_categories || ['sales', 'marketing', 'analytics', 'manager'];
const cutoff = Date.now() - CFG.window_days * 86400000;
const sleep = ms => new Promise(r => setTimeout(r, ms));

const errItem = msg => [{ json: { 
  source: 'remocate', id: 'error', title: '', company: '', url: '',
  location_raw: '', work_policy: 'unknown', posted_date: new Date().toISOString(),
  description_text: '', visa_sponsorship: false, heuristic_score: 0, 
  __error: 'remocate: ' + msg 
}}];

const clean = s => (s || '').replace(/\[([^\]]*)\]\([^)]*\)/g, '$1').replace(/<[^>]*>/g, ' ')
  .replace(/[#>*_`|]+/g, ' ').replace(/\s+/g, ' ').trim();

const out = []; 
const seenUrls = new Set();
let fetchFails = 0, marksFound = 0;

for (const cat of CATS) {
  let md = '';
  try {
    const res = await this.helpers.httpRequest({ 
      method: 'GET', json: true,
      url: 'https://r.jina.ai/https://www.remocate.app/job-categories/' + cat 
    });
    md = typeof res.content === 'string' ? res.content : (typeof res.data === 'string' ? res.data : '');
  } catch (e) { fetchFails++; continue; }

  if (md.length < 500) { fetchFails++; continue; }

  // Find date anchors (MM/DD/YYYY) which mark the end of a job's meta-line
  const dateRe = /(\d{1,2})\/(\d{1,2})\/(\d{4})/g; 
  let m; 
  const marks = [];
  while ((m = dateRe.exec(md)) !== null) {
    marks.push({ mm: +m[1], dd: +m[2], yy: +m[3], idx: m.index, end: m.index + m[0].length });
  }
  marksFound += marks.length;

  for (let i = 0; i < marks.length && out.length < 40; i++) {
    const lineStart = md.lastIndexOf('\n', marks[i].idx) + 1;
    const metaLine = md.slice(lineStart, marks[i].end);
    const nextStart = i + 1 < marks.length ? md.lastIndexOf('\n', marks[i + 1].idx) + 1 : md.length;
    const body = md.slice(marks[i].end, nextStart);

    const posted = Date.UTC(marks[i].yy, marks[i].mm - 1, marks[i].dd);
    if (!posted || posted < cutoff) continue; // Older than window_days

    const urlM = (metaLine + body).match(/https:\/\/www\.remocate\.app\/jobs\/[A-Za-z0-9-]+/);
    if (!urlM || seenUrls.has(urlM[0])) continue;
    seenUrls.add(urlM[0]);

    let title = '', company = 'unknown';
    const tc = metaLine.match(/^\s*([^\n•]+?)\s•\s(.+)$/);
    if (tc) {
      title = clean(tc[1]);
      const cut = tc[2].search(/(Contract based|Full-time|Part-time|Internship|Freelance|Contract)\b|[\u{1F1E6}-\u{1F1FF}]{2}|📞|🌟|📍/u);
      company = clean(cut > 0 ? tc[2].slice(0, cut) : tc[2].slice(0, 40)) || 'unknown';
    }

    const headTitle = body.match(/^##+\s*(.+)$/m);
    if (headTitle) title = clean(headTitle[1]) || title;

    const countryM = metaLine.match(/[\u{1F1E6}-\u{1F1FF}]{2}\s*([^📞🏠•]+?)(?=\s*(?:📞|🌟|$))/u);
    const salaryM = metaLine.match(/\$[\d,]+(?:\s*[–-]\s*\$[\d,]+)?/g);
    const empM = metaLine.match(/(Contract based|Full-time|Part-time|Internship|Freelance|Contract)\b/);

    out.push({ json: {
      source: 'remocate', id: urlM[0], title: title || 'unknown role', company,
      url: urlM[0],
      location_raw: countryM ? countryM[1].trim() : 'Worldwide',
      work_policy: /🏠\s*Remote|\bRemote\b/i.test(metaLine) ? 'remote' : 'unknown',
      posted_date: new Date(posted).toISOString(),
      description_text: clean([
        'Title: ' + title, 'Company: ' + company,
        'Type: ' + (empM ? empM[1] : 'unknown'),
        'Salary: ' + (salaryM ? salaryM.join(' – ') : 'not listed'),
        clean(body)
      ].join('\n')).slice(0, 6000),
      visa_sponsorship: /sponsor|relocation support|visa/i.test(metaLine + body),
      heuristic_score: 0
    }});
  }
  await sleep(1500); // Politeness between category pages
}

if (out.length) return out;
if (fetchFails === CATS.length) return errItem('all category fetches failed (Jina down/rate-limited)');
if (marksFound === 0) return errItem('format changed: no date anchors found');
return [];

// Job Radar v2 | Src LinkedIn (Code, run once for all items)
// LinkedIn public guest endpoint (no login, no cookies, $0). The laptop's residential IP is the
// reason this works: keep it to <= 20 list requests a run (enforced in jr_validate_config).
// Descriptions are fetched later by "Detail Fetch", only for postings that survive gate A and dedupe.
const SOURCE = 'linkedin';
const L = $('Load Config').first().json;
const S = (L.config.sources || {})[SOURCE] || {};
if (!S.enabled || S.mode !== 'guest' || L.due[SOURCE] === false) return [{ json: { source: SOURCE, __skip: 'disabled_or_not_due' } }];

const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0 Safari/537.36';
const WT = { onsite: 1, remote: 2, hybrid: 3 };
const EXP = { internship: 1, entry: 2, associate: 3, mid_senior: 4, director: 5, executive: 6 };
const sleep = ms => new Promise(r => setTimeout(r, ms));
const decode = s => String(s || '').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#39;|&#x27;/g, "'").replace(/&nbsp;/g, ' ');
const strip = s => decode(String(s || '').replace(/<[^>]*>/g, ' ')).replace(/\s+/g, ' ').trim();
const pick = (html, re) => { const m = html.match(re); return m ? strip(m[1]) : ''; };

const windowSec = Math.max(1, Math.min(30, Number(L.config.freshness.window_days) || 7)) * 86400;
const out = [];
const seen = new Set();
let requests = 0, blocked = false, lastError = '';

for (const s of (S.searches || [])) {
  if (blocked) break;
  const modes = (s.work_types || []).filter(w => WT[w]);
  const mode = modes.length === 1 ? modes[0] : 'unknown';
  for (let page = 0; page < Math.min(3, Number(S.max_pages) || 1); page++) {
    // Built by hand: the n8n Code-node sandbox has no URLSearchParams.
    const params = [['keywords', s.keywords], ['location', s.location || 'Worldwide'], ['f_TPR', 'r' + windowSec],
                    ['sortBy', 'DD'], ['start', String(page * 10)]];
    if (modes.length) params.push(['f_WT', modes.map(w => WT[w]).join(',')]);
    const exps = (s.experience || []).map(e => EXP[e]).filter(Boolean);
    if (exps.length) params.push(['f_E', exps.join(',')]);
    const qs = params.map(([k, v]) => k + '=' + encodeURIComponent(v)).join('&');
    let html = '';
    try {
      requests++;
      html = String(await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://www.linkedin.com/jobs-guest/jobs/api/seeMoreJobPostings/search?' + qs,
        headers: { 'User-Agent': UA, 'Accept-Language': 'en-US,en;q=0.9', 'Accept': 'text/html' },
        json: false, timeout: 20000
      }));
    } catch (e) {
      lastError = String(e.message || e).slice(0, 160);
      if (/429|999|403/.test(lastError)) blocked = true;   // LinkedIn throttled this IP: stop for today
      break;
    }
    const cards = html.split(/<li[\s>]/).slice(1);
    if (!cards.length) break;
    for (const c of cards) {
      const id = (c.match(/urn:li:jobPosting:(\d+)/) || c.match(/\/jobs\/view\/[^"?]*?-(\d{6,})/) || [])[1];
      if (!id || seen.has(id)) continue;
      seen.add(id);
      const dt = (c.match(/<time[^>]*datetime="(\d{4}-\d{2}-\d{2})"/) || [])[1];
      out.push({ json: {
        source: SOURCE, source_id: id,
        title: pick(c, /base-search-card__title[^>]*>([\s\S]*?)<\/h3>/),
        company: pick(c, /base-search-card__subtitle[^>]*>([\s\S]*?)<\/h4>/) || 'unknown',
        url: 'https://www.linkedin.com/jobs/view/' + id + '/',
        location_raw: pick(c, /job-search-card__location[^>]*>([\s\S]*?)<\/span>/),
        work_mode: mode,
        posted_date: dt ? new Date(dt + 'T12:00:00Z').toISOString() : new Date().toISOString(),
        posted_estimated: !dt,
        description_text: '',
        needs_detail: !!S.detail,
        detail: { mode: 'linkedin', id },
        search: s.keywords
      } });
    }
    if (cards.length < 10) break;
    await sleep(2500);
  }
  await sleep(2500);
}

if (!out.length) {
  return [{ json: { source: SOURCE, __error: SOURCE + ': ' + (lastError || 'no cards parsed (' + requests + ' requests): markup changed or no results') } }];
}
if (lastError) out.push({ json: { source: SOURCE, __error: SOURCE + ': partial, ' + lastError } });
return out;

// Job Radar v2 | Src Boards (Code, run once for all items)
// Generic "Jina Reader bridge" for job boards without an API (ADR-JR-29). Each board is DATA in the
// config (list_urls + job_url_regex), edited from the console: fixing a board never needs a code change.
// r.jina.ai renders JavaScript pages (headless browser) and returns markdown. Free without a key at
// 20 requests/minute per IP, so requests are paced at 3.5 s. Set JINA_API_KEY in n8n env to go faster.
const L = $('Load Config').first().json;
const boards = ((L.config.sources || {}).boards || []).filter(b => b.enabled && L.due[b.key] !== false);
if (!boards.length) return [{ json: { source: 'boards', __skip: 'none_enabled_or_due' } }];

let JINA_KEY = '';
try { JINA_KEY = $env.JINA_API_KEY || ''; } catch (e) { JINA_KEY = ''; }
const headers = { 'Accept': 'application/json', 'X-Timeout': '25', 'X-Return-Format': 'markdown' };
if (JINA_KEY) headers.Authorization = 'Bearer ' + JINA_KEY;
const PACE = JINA_KEY ? 800 : 3500;
const sleep = ms => new Promise(r => setTimeout(r, ms));

const GENERIC = /^(apply( now)?|view( job| role| details)?|see (job|more|details)|learn more|details|read more|open|new|featured|save|share)$/i;
const cleanText = s => String(s || '')
  .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')            // images
  .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')           // nested links
  .replace(/[#>*_`|]+/g, ' ').replace(/\\/g, '').replace(/\s+/g, ' ').trim();

// "3d ago", "8h ago", "today", "Oct 24", "2026-10-24" -> ISO date, else null
const parseWhen = (text) => {
  const t = String(text || '').toLowerCase();
  const now = Date.now();
  let m = t.match(/\b(\d{1,3})\s*(m|min|mins|minutes?|h|hr|hrs|hours?|d|days?|w|wk|weeks?|mo|months?)\b\.?\s*ago/);
  if (m) {
    const n = Number(m[1]); const u = m[2];
    const ms = /^m(in|ins|inutes?)?$/.test(u) ? 60e3 : /^h/.test(u) ? 3600e3 : /^d/.test(u) ? 86400e3 : /^w/.test(u) ? 7 * 86400e3 : 30 * 86400e3;
    return new Date(now - n * ms).toISOString();
  }
  if (/\b(just now|today|new)\b/.test(t)) return new Date(now).toISOString();
  if (/\byesterday\b/.test(t)) return new Date(now - 86400e3).toISOString();
  m = t.match(/\b(20\d\d-\d\d-\d\d)\b/);
  if (m) return new Date(m[1] + 'T12:00:00Z').toISOString();
  m = t.match(/\b(jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec)[a-z]*\.?\s+(\d{1,2})(?:,?\s+(20\d\d))?\b/);
  if (m) {
    const months = { jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5, jul: 6, aug: 7, sep: 8, sept: 8, oct: 9, nov: 10, dec: 11 };
    const y = m[3] ? Number(m[3]) : new Date().getUTCFullYear();
    let d = Date.UTC(y, months[m[1]], Number(m[2]), 12);
    if (!m[3] && d > now + 2 * 86400e3) d = Date.UTC(y - 1, months[m[1]], Number(m[2]), 12);
    return new Date(d).toISOString();
  }
  return null;
};
// Last resort: "/job/acme-gtm-engineer-berlin/" -> "acme gtm engineer berlin"
const slugTitle = u => {
  const parts = String(u).split('?')[0].replace(/\/+$/, '').split('/');
  const slug = decodeURIComponent(parts[parts.length - 1] || '');
  // Trailing ids are dropped only when they contain a digit ("-rec0lebnhiss", "-dvs9j7"), never words like "-remote".
  return /[a-z]{3,}-[a-z]{3,}/i.test(slug) ? slug.replace(/-(?:rec)?(?=[a-z0-9]*\d)[a-z0-9]{6,}$/i, '').replace(/[-_]+/g, ' ').trim() : '';
};
const modeOf = t => /\bhybrid\b/i.test(t) ? 'hybrid' : /\b(remote|anywhere|worldwide|work from home|fully remote)\b/i.test(t) ? 'remote'
  : /\b(on[- ]?site|in[- ]office|onsite)\b/i.test(t) ? 'onsite' : 'unknown';
const seniorityOf = t => {
  const m = String(t || '').match(/\b(entry[- ]level|junior|intern(ship)?|mid[- ]level|senior|lead|staff\+?|exec(utive)?|director)\b/i);
  return m ? m[1].toLowerCase().replace(/\s+/g, '-') : '';
};

const out = [];
for (const b of boards) {
  let urlRe;
  try { urlRe = new RegExp('^(?:' + b.job_url_regex + ')', 'i'); }
  catch (e) { out.push({ json: { source: b.key, __error: b.key + ': bad job_url_regex (' + e.message + ')' } }); continue; }
  const seenUrl = new Set();
  let pages = 0, fails = 0, links = 0, lastErr = '';
  for (const listUrl of (b.list_urls || [])) {
    if (out.filter(i => i.json.source === b.key && i.json.url).length >= b.max_items) break;
    let md = '';
    try {
      const res = await this.helpers.httpRequest({ method: 'GET', url: 'https://r.jina.ai/' + listUrl, headers, json: true, timeout: 45000 });
      md = typeof res === 'string' ? res : String((res && res.data && res.data.content) || (res && res.content) || '');
      pages++;
    } catch (e) { fails++; lastErr = String(e.message || e).slice(0, 140); await sleep(PACE); continue; }
    const linkRe = /\[((?:[^\[\]]|\[[^\]]*\])*)\]\((https?:\/\/[^)\s]+)(?:\s+"[^"]*")?\)/g;
    const found = [];
    let m;
    while ((m = linkRe.exec(md)) !== null) {
      const href = m[2].replace(/[.,;]+$/, '');
      if (!urlRe.test(href)) continue;
      links++;
      found.push({ text: m[1], href, start: m.index, end: linkRe.lastIndex });
    }
    for (let i = 0; i < found.length; i++) {
      const f = found[i];
      const url = f.href.split('#')[0];
      if (seenUrl.has(url)) continue;
      // Logo/image links carry no text: let a later link to the same job supply the title.
      if (!cleanText(f.text) && found.slice(i + 1).some(g => g.href.split('#')[0] === url && cleanText(g.text))) continue;
      const ctxEnd = i + 1 < found.length ? found[i + 1].start : Math.min(md.length, f.end + 500);
      const context = cleanText(md.slice(f.end, Math.min(ctxEnd, f.end + 500)));
      let title = cleanText(f.text);
      if (!title || GENERIC.test(title)) title = slugTitle(url);           // slug beats neighbouring card text
      if (!title || GENERIC.test(title)) {
        const before = cleanText(md.slice(Math.max(0, f.start - 300), f.start)).split(/\s{2,}|\n/).filter(Boolean);
        title = before.length ? before[before.length - 1].slice(-160) : '';
      }
      title = title.replace(/\s+(?:\d{1,3}\s*(?:m|min|h|hr|d|w|mo)[a-z]*\s+ago|today|yesterday|new|featured)\b.*$/i, '').trim();
      if (!title || GENERIC.test(title)) continue;
      seenUrl.add(url);
      const blob = title + ' ' + context;
      const posted = parseWhen(blob);
      out.push({ json: {
        source: b.key, source_id: url, title: title.slice(0, 220), company: 'unknown', url,
        location_raw: '', work_mode: modeOf(blob), seniority_hint: seniorityOf(blob),
        posted_date: posted || new Date().toISOString(), posted_estimated: !posted,
        description_text: '', list_context: context.slice(0, 400),
        needs_detail: b.detail === 'jina', detail: { mode: b.detail === 'jina' ? 'jina' : 'none', url }
      } });
      if (seenUrl.size >= b.max_items) break;
    }
    await sleep(PACE);
  }
  if (!seenUrl.size) {
    out.push({ json: { source: b.key, __error: b.key + ': ' + (fails ? 'fetch failed on ' + fails + ' page(s): ' + lastErr
      : 'parser_no_links (' + pages + ' page(s), regex matched ' + links + ' links): fix job_url_regex in the console') } });
  }
}
return out;

// Job Radar v2 | Reddit Queries (Code, run once for all items)
// Reddit closed self-serve API keys (Nov 2025), blocks logged-out .json (since May 2026) and ends RSS on
// 2026-11-13. So Reddit is read through a search index instead: Tavily, already in your n8n credentials.
// One item per query -> "Tavily Search" (HTTP Request, credential "Tavily Header Auth") -> "Reddit Mapper".
// Budget: 1 credit per basic search; 6 queries x 30 days = 180 of the 1,000 free monthly credits.
const L = $('Load Config').first().json;
const S = (L.config.sources || {}).reddit || {};
if (!S.enabled || S.mode !== 'tavily' || L.due.reddit === false) return [];   // branch stops; Merge New still runs

const queries = (S.queries || []).slice(0, Math.max(0, Number(S.max_queries) || 0));
return queries.map(q => ({ json: {
  query: q,
  body: {
    query: q,
    search_depth: 'basic',
    topic: 'general',
    time_range: S.time_range === 'week' ? 'week' : 'day',
    max_results: 10,
    include_domains: ['reddit.com'],
    include_answer: false,
    include_raw_content: false
  }
} }));

// Job Radar v2 | Reddit Mapper (Code, run once for all items)
// Input: one Tavily response per query (HTTP node "Tavily Search", On Error = Continue).
// Keeps only posts from the configured subreddits, canonicalises the URL, and tags "[For Hire]" offers
// (people selling services) so gate A drops them with a visible reason instead of silently.
const SOURCE = 'reddit';
const L = $('Load Config').first().json;
const S = (L.config.sources || {}).reddit || {};
const subs = new Set((S.subreddits || []).map(s => String(s).toLowerCase().replace(/^r\//, '')));
const queries = $('Reddit Queries').all().map(i => i.json.query);

const out = [];
const seen = new Set();
const errors = [];
$input.all().forEach((it, idx) => {
  const res = it.json || {};
  if (res.error || !Array.isArray(res.results)) {
    errors.push((queries[idx] || 'query ' + idx) + ': ' + String((res.error && (res.error.message || res.error)) || 'no results field').slice(0, 120));
    return;
  }
  for (const r of res.results) {
    const m = String(r.url || '').match(/reddit\.com\/r\/([A-Za-z0-9_]+)\/comments\/([a-z0-9]+)/i);
    if (!m) continue;
    if (subs.size && !subs.has(m[1].toLowerCase())) continue;
    const url = 'https://www.reddit.com/r/' + m[1] + '/comments/' + m[2] + '/';
    if (seen.has(url)) continue;
    seen.add(url);
    const title = String(r.title || '').replace(/\s*:\s*r\/\w+\s*$/i, '').replace(/\s*[-|]\s*reddit\s*$/i, '').trim();
    const text = String(r.content || '').replace(/\s+/g, ' ').trim();
    const forHire = /\[\s*for\s*hire\s*\]|^\s*for\s*hire\b|\(for hire\)/i.test(title);
    const hiring = /\[\s*hiring\s*\]|\bhiring\b|\blooking for\b|\bneed(ed)?\b|\bseeking\b|\bwanted\b|\bpaid\b/i.test(title + ' ' + text.slice(0, 300));
    out.push({ json: {
      source: SOURCE, source_id: m[2], title: title.slice(0, 220), company: 'r/' + m[1], url,
      location_raw: /\bremote\b/i.test(title + ' ' + text) ? 'Remote' : '',
      work_mode: /\bremote\b/i.test(title + ' ' + text) ? 'remote' : 'unknown',
      kind: 'gig',
      posted_date: new Date().toISOString(), posted_estimated: true,   // time_range=day bounds the age
      description_text: (title + '\n' + text).slice(0, 6000),
      needs_detail: false,
      gate_hint: forHire ? 'reddit_for_hire' : (hiring ? '' : 'reddit_not_hiring'),
      subreddit: m[1]
    } });
  }
});
if (errors.length && !out.length) return [{ json: { source: SOURCE, __error: SOURCE + ': ' + errors.join(' | ').slice(0, 300) } }];
if (errors.length) out.push({ json: { source: SOURCE, __error: SOURCE + ': partial, ' + errors.join(' | ').slice(0, 300) } });
if (!out.length) return [{ json: { source: SOURCE, __skip: 'no_results' } }];
return out;

// Job Radar v2 | Src ATS (Code, run once for all items)
// Company watchlist read straight from public ATS job-board APIs (no key, stable JSON, full descriptions):
//   Greenhouse  https://boards-api.greenhouse.io/v1/boards/{token}/jobs?content=true
//   Lever       https://api.lever.co/v0/postings/{token}?mode=json
//   Ashby       https://api.ashbyhq.com/posting-api/job-board/{token}
// Companies live in config sources.ats.companies [{name, ats, token}] and are edited in the console.
const SOURCE = 'ats';
const L = $('Load Config').first().json;
const S = (L.config.sources || {})[SOURCE] || {};
if (!S.enabled || L.due[SOURCE] === false) return [{ json: { source: SOURCE, __skip: 'disabled_or_not_due' } }];
const companies = S.companies || [];
if (!companies.length) return [{ json: { source: SOURCE, __skip: 'no_companies' } }];

const cutoff = Date.now() - (Number(L.config.freshness.window_days) || 7) * 86400000;
const cap = Number(S.max_per_company) || 30;
const sleep = ms => new Promise(r => setTimeout(r, ms));
const decode = s => String(s || '').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
  .replace(/&#39;|&#x27;/g, "'").replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
const strip = s => decode(decode(String(s || ''))).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
const mode = (wt, remote, loc) => {
  const w = String(wt || '').toLowerCase();
  if (w.includes('hybrid')) return 'hybrid';
  if (w.includes('remote') || remote === true) return 'remote';
  if (w.includes('onsite') || w.includes('on-site') || w.includes('in office')) return 'onsite';
  return /\bremote\b/i.test(loc || '') ? 'remote' : (/\bhybrid\b/i.test(loc || '') ? 'hybrid' : 'unknown');
};

const out = [];
const errors = [];
for (const c of companies) {
  try {
    let rows = [];
    if (c.ats === 'greenhouse') {
      const r = await this.helpers.httpRequest({ method: 'GET', json: true, timeout: 20000,
        url: 'https://boards-api.greenhouse.io/v1/boards/' + encodeURIComponent(c.token) + '/jobs?content=true' });
      rows = (r.jobs || []).map(j => ({
        id: String(j.id), title: j.title, url: j.absolute_url, loc: (j.location && j.location.name) || '',
        posted: j.first_published || j.updated_at, desc: strip(j.content), wm: mode('', null, (j.location && j.location.name) || '')
      }));
    } else if (c.ats === 'lever') {
      const r = await this.helpers.httpRequest({ method: 'GET', json: true, timeout: 20000,
        url: 'https://api.lever.co/v0/postings/' + encodeURIComponent(c.token) + '?mode=json' });
      rows = (Array.isArray(r) ? r : []).map(j => ({
        id: j.id, title: j.text, url: j.hostedUrl, loc: (j.categories && j.categories.location) || '',
        posted: j.createdAt, emp: j.categories && j.categories.commitment,
        desc: strip([j.descriptionPlain || j.description, ...(j.lists || []).map(l => l.text + ': ' + strip(l.content)), j.additionalPlain].join(' ')),
        wm: mode(j.workplaceType, null, (j.categories && j.categories.location) || '')
      }));
    } else if (c.ats === 'ashby') {
      const r = await this.helpers.httpRequest({ method: 'GET', json: true, timeout: 20000,
        url: 'https://api.ashbyhq.com/posting-api/job-board/' + encodeURIComponent(c.token) });
      rows = (r.jobs || []).filter(j => j.isListed !== false).map(j => ({
        id: j.id || j.jobUrl, title: j.title, url: j.jobUrl, loc: j.location || '', posted: j.publishedAt,
        emp: j.employmentType, desc: strip(j.descriptionPlain || j.descriptionHtml), wm: mode(j.workplaceType, j.isRemote, j.location)
      }));
    }
    const fresh = rows.filter(j => j.url && (!j.posted || new Date(j.posted).getTime() >= cutoff)).slice(0, cap);
    for (const j of fresh) {
      out.push({ json: {
        source: SOURCE, source_id: c.ats + ':' + c.token + ':' + j.id, title: j.title, company: c.name, url: j.url,
        location_raw: j.loc, work_mode: j.wm, employment_type_raw: j.emp || '',
        posted_date: j.posted ? new Date(j.posted).toISOString() : new Date().toISOString(), posted_estimated: !j.posted,
        description_text: j.desc.slice(0, 6000), needs_detail: false, ats_company: c.name
      } });
    }
  } catch (e) {
    errors.push(c.name + ' (' + c.ats + '/' + c.token + '): ' + String(e.message || e).slice(0, 80));
  }
  await sleep(400);
}
if (errors.length) out.push({ json: { source: SOURCE, __error: SOURCE + ': ' + errors.join(' | ').slice(0, 400) } });
if (!out.length) return [{ json: { source: SOURCE, __skip: 'nothing_fresh' } }];
return out;

// Job Radar v2 | Src Working Nomads (Code, run once for all items)
// Free public JSON feed of curated remote jobs: https://www.workingnomads.com/api/exposed_jobs/
// Fields: url, title, description (HTML), company_name, category_name, tags, location, pub_date.
const SOURCE = 'working-nomads';
const L = $('Load Config').first().json;
const S = (L.config.sources || {})[SOURCE] || {};
if (!S.enabled || L.due[SOURCE] === false) return [{ json: { source: SOURCE, __skip: 'disabled_or_not_due' } }];
const strip = s => String(s || '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
try {
  const rows = await this.helpers.httpRequest({ method: 'GET', json: true, timeout: 30000,
    url: 'https://www.workingnomads.com/api/exposed_jobs/', headers: { 'User-Agent': 'JobRadar/2.0' } });
  const list = Array.isArray(rows) ? rows : [];
  if (!list.length) return [{ json: { source: SOURCE, __error: SOURCE + ': empty response (format changed?)' } }];
  return list.filter(j => j.url && j.title).map(j => ({ json: {
    source: SOURCE, source_id: j.url, title: j.title, company: j.company_name || 'unknown', url: j.url,
    location_raw: j.location || 'Remote', work_mode: 'remote',
    posted_date: j.pub_date ? new Date(j.pub_date).toISOString() : new Date().toISOString(), posted_estimated: !j.pub_date,
    description_text: strip(j.description).slice(0, 6000), needs_detail: false,
    tags: String(j.tags || '').split(',').map(t => t.trim()).filter(Boolean), category: j.category_name || ''
  } }));
} catch (e) {
  return [{ json: { source: SOURCE, __error: SOURCE + ': ' + String(e.message || e).slice(0, 200) } }];
}

// Job Radar v2 | Normalize (Code, run once for all items). Input: "Merge All".
// One schema for every source (the 12 v1 mappers + the v2 adapters), canonical URLs, work mode,
// employment type and kind (job or gig). Error and skip markers are passed through untouched so
// "Run Stats" can count them per source; disabled sources are dropped here (their fetch still ran).
const L = $('Load Config').first().json;
const S = L.config.sources || {};
const boardKeys = new Map((S.boards || []).map(b => [b.key, b]));
const enabled = src => S[src] ? !!S[src].enabled : (boardKeys.has(src) ? !!boardKeys.get(src).enabled : true);

const DROP_PARAMS = /^(utm_|ref$|ref_|refid|trk|tracking|src$|source$|gh_src|lever-|ashby_|fbclid|gclid|mc_)/i;
// HN Who is Hiring sends HTML-entity encoded text ("https:&#x2F;&#x2F;acme.com", "R&amp;D"): decode first (run 1, 2026-10-30).
const unent = s => String(s || '').replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCharCode(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (_, d) => String.fromCharCode(Number(d))).replace(/&quot;/g, '"').replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
// String-based on purpose: the n8n Code-node sandbox has no URL / URLSearchParams globals (probe, 2026-10-30).
const canonUrl = u => {
  const m = unent(u).trim().match(/^(https?):\/\/([^\/?#\s]+)([^?#\s]*)(\?[^#\s]*)?/i);
  if (!m) return '';
  const query = (m[4] || '').slice(1).split('&').filter(p => p && !DROP_PARAMS.test(decodeURIComponent(p.split('=')[0] || '')));
  return m[1].toLowerCase() + '://' + m[2].toLowerCase() + (m[3] || '/') + (query.length ? '?' + query.join('&') : '');
};
const detectMode = t => /\bhybrid\b/i.test(t) ? 'hybrid'
  : /\b(fully remote|remote[- ]first|100% remote|remote|anywhere|worldwide|work from home|wfh|distributed team)\b/i.test(t) ? 'remote'
  : /\b(on[- ]?site|in[- ]office|office[- ]based|onsite)\b/i.test(t) ? 'onsite' : 'unknown';
const detectEmployment = t =>
  /\b(intern|internship|praktikum|werkstudent|working student)\b/i.test(t) ? 'internship'
  : /\b(freelance|freelancer)\b/i.test(t) ? 'freelance'
  : /\b(contract|contractor|fixed[- ]term|temporary)\b/i.test(t) ? 'contract'
  : /\bpart[- ]time\b/i.test(t) ? 'part_time'
  : /\bfull[- ]time\b/i.test(t) ? 'full_time' : 'unknown';
const GIG = /\b(freelance|freelancer|gig|one[- ]off|short[- ]term|project[- ]based|per hour|\/\s?hr|hourly|fixed[- ]price|budget|bounty|paid task|small task)\b/i;
// Community job boards (Clay, n8n forums) carry freelance asks, not employment (run 2, 2026-10-30).
const GIG_SOURCES = new Set(['reddit', 'contra', 'clay-community', 'n8n-community']);

const out = [];
const seen = new Set();
for (const it of $input.all()) {
  const j = it.json || {};
  if (j.__skip || j.__error) { out.push({ json: { source: j.source || 'unknown', __skip: j.__skip, __error: j.__error } }); continue; }
  if (!j.url || !j.source) continue;
  if (!enabled(j.source)) { out.push({ json: { source: j.source, __skip: 'disabled' } }); continue; }
  const url = canonUrl(j.url);
  if (!url || seen.has(url)) continue;
  seen.add(url);

  const title = unent(j.title).replace(/\s+/g, ' ').trim();
  const desc = String(j.description_text || '').trim();
  const head = [title, j.location_raw, j.employment_type_raw, j.list_context, desc.slice(0, 600)].filter(Boolean).join(' | ');
  let mode = j.work_mode || (j.work_policy === 'remote' ? 'remote' : j.work_policy === 'onsite' ? 'onsite' : 'unknown');
  if (!['remote', 'hybrid', 'onsite'].includes(mode)) mode = detectMode([title, j.location_raw, j.list_context].join(' '));
  if (mode === 'remote' && /\bhybrid\b/i.test(title + ' ' + (j.location_raw || ''))) mode = 'hybrid';   // "Remote / Hybrid" titles
  const employment = detectEmployment(head);
  const kind = j.kind === 'gig' || GIG_SOURCES.has(j.source) || employment === 'freelance' || GIG.test(title + ' ' + desc.slice(0, 300)) ? 'gig' : 'job';
  const posted = new Date(j.posted_date);
  const postedOk = !isNaN(posted.getTime());

  out.push({ json: {
    source: j.source,
    source_id: String(j.source_id || j.id || url),
    url,
    title: title || '(untitled)',
    company: unent(j.company || 'unknown').trim() || 'unknown',
    location_raw: String(j.location_raw || '').trim(),
    work_mode: mode,
    employment_type: employment,
    kind,
    posted_date: postedOk ? posted.toISOString() : new Date().toISOString(),
    posted_estimated: !postedOk || !!j.posted_estimated,
    description_text: desc.slice(0, 6000),
    needs_detail: !!j.needs_detail && desc.length < 200,
    detail: j.detail || null,
    visa_flag: j.source === 'arbeitnow' ? j.visa_sponsorship === true : (j.visa_sponsorship === true ? true : null),
    seniority_hint: j.seniority_hint || '',
    gate_hint: j.gate_hint || '',
    list_context: j.list_context || ''
  } });
}
return out.length ? out : [{ json: { source: 'normalize', __skip: 'no_items' } }];

// Job Radar v2 | Gate A (Code, run once for all items). Input: "Normalize".
// Deterministic gates on metadata only (title, location, dates, source flags). Cheap, so it runs on
// everything. Every item gets gate = pass|drop plus a reason code; "Ingest" records all of them so
// the console can show what was dropped and why. Rule: drop only on clear evidence.
const L = $('Load Config').first().json;
const C = L.config;
const esc = s => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const termRe = terms => (terms && terms.length)
  ? new RegExp('(?:^|[^a-z0-9])(' + terms.map(t => esc(String(t).toLowerCase())).join('|') + ')(?=$|[^a-z0-9])', 'i') : null;
const hit = (re, text) => { if (!re) return ''; const m = String(text || '').match(re); return m ? m[1] : ''; };
const safeRe = (src, fb) => { try { return new RegExp(src, 'i'); } catch (e) { return fb; } };

const roleRe = termRe(C.search.role_terms);
const blockRe = termRe(C.search.title_block_terms);
const seniorRe = safeRe(C.search.title_senior_regex, /$^/);
const juniorRe = safeRe(C.search.title_junior_regex, /$^/);
const skillRes = (C.search.skills || []).map(s => termRe([s]));
const okRe = termRe(C.work_modes.remote.regions_ok);
const locBlockRe = termRe(C.work_modes.remote.location_block);
const countryRe = termRe(C.visa.target_countries);
const SENIOR_HINT = /^(mid-level|mid|senior|lead|staff\+?|exec|executive|director|mid_senior)$/i;
const cutoff = Date.now() - C.freshness.window_days * 86400000;
const minHits = Number(C.search.min_skill_hits) || 0;
const allowedEmployment = new Set(C.opportunity.employment_types || []);
const arbeitnowVisaOnly = !!(C.sources.arbeitnow && C.sources.arbeitnow.visa_only);

function gate(j) {
  if (j.gate_hint) return ['drop', j.gate_hint, ''];
  if (j.kind === 'job' && !C.opportunity.jobs) return ['drop', 'kind_disabled', 'job'];
  if (j.kind === 'gig' && !C.opportunity.gigs) return ['drop', 'kind_disabled', 'gig'];
  if (!allowedEmployment.has(j.employment_type)) return ['drop', 'employment_type', j.employment_type];
  if (new Date(j.posted_date).getTime() < cutoff) return ['drop', 'stale', j.posted_date.slice(0, 10)];

  const title = j.title.toLowerCase();
  const blocked = hit(blockRe, title);
  if (blocked) return ['drop', 'title_blocked', blocked];
  const senior = (title.match(seniorRe) || [])[0];
  if (senior && !juniorRe.test(title)) return ['drop', 'title_senior', senior];
  if (j.seniority_hint && SENIOR_HINT.test(j.seniority_hint)) return ['drop', 'seniority_hint', j.seniority_hint];

  const role = hit(roleRe, title);
  if (!role) {
    const desc = j.description_text || '';
    const hits = desc.length >= 200 ? skillRes.filter(re => re && re.test(desc)).length : 0;
    if (hits < Math.max(1, minHits)) return ['drop', 'role_mismatch', desc.length >= 200 ? hits + ' skill hits' : 'title only'];
  }

  if (j.source === 'arbeitnow' && arbeitnowVisaOnly && j.visa_flag !== true) return ['drop', 'visa_flag_false', 'arbeitnow'];

  const mode = j.work_mode;
  const wm = C.work_modes;
  if (mode === 'remote') {
    if (!wm.remote.enabled) return ['drop', 'mode_disabled', 'remote'];
    const loc = j.location_raw || '';
    const blockedLoc = hit(locBlockRe, loc);
    if (blockedLoc && !hit(okRe, loc)) return ['drop', 'remote_region', blockedLoc];
  } else if (mode === 'hybrid' || mode === 'onsite') {
    if (!wm[mode].enabled) return ['drop', 'mode_disabled', mode];
    if (countryRe && j.location_raw && !hit(countryRe, j.location_raw)) return ['drop', 'country_not_target', j.location_raw.slice(0, 60)];
  } else if (wm.unknown_policy === 'drop') {
    return ['drop', 'mode_unknown', ''];
  }
  return ['pass', '', ''];
}

const out = [];
for (const it of $input.all()) {
  const j = it.json;
  if (!j.url) { out.push({ json: j }); continue; }               // skip/error markers pass through for stats
  const [g, reason, detail] = gate(j);
  out.push({ json: Object.assign({}, j, {
    gate_a: g, gate_a_reason: reason,
    _ingest: {
      url: j.url, source: j.source, kind: j.kind, title: j.title, company: j.company, location_raw: j.location_raw,
      work_mode: j.work_mode, employment_type: j.employment_type, posted_date: j.posted_date,
      gate: g, reason, detail: String(detail || '').slice(0, 300)
    }
  }) });
}
return out;

// Job Radar v2 | Rejoin (Code, run once for all items). Input: "Ingest" (rows from jr_ingest).
// jr_ingest returns only postings worth processing (new, or retries). Descriptions never went to the
// database, so the full items are taken back from "Gate A" by URL.
const back = $input.all().map(i => i.json).filter(r => r && r.posting_id && r.url);
if (!back.length) return [{ json: { __empty: true } }];
const byUrl = new Map($('Gate A').all().map(i => i.json).filter(j => j.url).map(j => [j.url, j]));
const out = [];
for (const r of back) {
  const j = byUrl.get(r.url);
  if (!j) continue;
  const { _ingest, ...rest } = j;
  out.push({ json: Object.assign(rest, { posting_id: r.posting_id, retry: r.retry === true || r.retry === 't' }) });
}
return out.length ? out : [{ json: { __empty: true } }];

// Job Radar v2 | Detail Fetch (Code, run once for all items). Input: "Rejoin".
// List-only sources (LinkedIn, Jina boards) arrive without a description. Fetch it only now, after
// gate A and dedupe, and only for the best llm.detail_cap candidates (title role match and junior
// words first). The rest is deferred (stays queued) and retried next run while still fresh.
const L = $('Load Config').first().json;
const C = L.config;
const items = $input.all().map(i => i.json).filter(j => j.url);
if (!items.length) return [{ json: { __empty: true } }];

const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0 Safari/537.36';
let JINA_KEY = '';
try { JINA_KEY = $env.JINA_API_KEY || ''; } catch (e) { JINA_KEY = ''; }
const sleep = ms => new Promise(r => setTimeout(r, ms));
const decode = s => String(s || '').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#39;|&#x27;/g, "'").replace(/&nbsp;/g, ' ');
const strip = s => decode(String(s || '').replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|li|h\d)>/gi, '\n').replace(/<[^>]*>/g, ' '))
  .replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
const mdClean = s => String(s || '').replace(/!\[[^\]]*\]\([^)]*\)/g, ' ').replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
  .replace(/[#>*_`|]+/g, ' ').replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
const junior = (() => { try { return new RegExp(C.search.title_junior_regex, 'i'); } catch (e) { return /$^/; } })();
const prio = j => (junior.test(j.title) ? 2 : 0) + (/\b(gtm|automation|revops|n8n|clay|hubspot|crm)\b/i.test(j.title) ? 1 : 0);

// Budget is spent per attempted fetch, in priority order. When LinkedIn throttles, its remaining items are
// deferred without using budget, so the slots go to the next Jina candidates (run 3, 2026-10-30: 29 LinkedIn
// deferrals had blocked 7 Jina fetches).
const need = items.filter(j => j.needs_detail && j.detail && j.detail.mode !== 'none').sort((a, b) => prio(b) - prio(a));
const budget = Math.max(0, Number(C.llm.detail_cap) || 0);
let used = 0;
const startedAt = Date.now();
let liBlocked = false;
let timeLimitS = 280;
try { timeLimitS = Math.max(120, (Number($env.N8N_RUNNERS_TASK_TIMEOUT) || 300) - 20); } catch (e) { /* default */ }

for (const j of items) if (!j.needs_detail || !j.detail || j.detail.mode === 'none') j.detail_status = 'not_needed';
for (const j of need) {
  if (j.detail.mode === 'linkedin' && liBlocked) { j.detail_status = 'deferred'; continue; }   // no budget used
  if (used >= budget) { j.detail_status = 'deferred'; continue; }
  if ((Date.now() - startedAt) / 1000 > timeLimitS) { j.detail_status = 'deferred'; continue; }
  used++;
  try {
    if (j.detail.mode === 'linkedin') {
      const html = String(await this.helpers.httpRequest({ method: 'GET', json: false, timeout: 20000,
        url: 'https://www.linkedin.com/jobs-guest/jobs/api/jobPosting/' + j.detail.id,
        headers: { 'User-Agent': UA, 'Accept-Language': 'en-US,en;q=0.9' } }));
      const body = (html.match(/show-more-less-html__markup[^>]*>([\s\S]*?)<\/div>/) || [])[1] || '';
      const crit = {};
      const re = /description__job-criteria-subheader[^>]*>([\s\S]*?)<\/h3>[\s\S]*?description__job-criteria-text[^>]*>([\s\S]*?)<\/span>/g;
      let m;
      while ((m = re.exec(html)) !== null) crit[strip(m[1]).toLowerCase()] = strip(m[2]);
      j.description_text = strip(body).slice(0, 6000);
      if (crit['seniority level']) j.seniority_hint = crit['seniority level'].toLowerCase().replace(/\s+/g, '-');
      if (crit['employment type'] && j.employment_type === 'unknown') {
        const e = crit['employment type'].toLowerCase();
        j.employment_type = e.includes('intern') ? 'internship' : e.includes('contract') ? 'contract' : e.includes('part') ? 'part_time'
          : e.includes('full') ? 'full_time' : e.includes('temporary') ? 'contract' : 'unknown';
      }
      await sleep(2000);
    } else if (j.detail.mode === 'jina') {
      const headers = { 'Accept': 'application/json', 'X-Timeout': '25', 'X-Return-Format': 'markdown' };
      if (JINA_KEY) headers.Authorization = 'Bearer ' + JINA_KEY;
      const res = await this.helpers.httpRequest({ method: 'GET', url: 'https://r.jina.ai/' + (j.detail.url || j.url), headers, json: true, timeout: 45000 });
      const md = typeof res === 'string' ? res : String((res && res.data && res.data.content) || (res && res.content) || '');
      const titleFromPage = res && res.data && res.data.title;
      j.description_text = mdClean(md).slice(0, 6000);
      if (titleFromPage && (j.title === '(untitled)' || j.title.length > 140)) j.title = String(titleFromPage).slice(0, 200);
      await sleep(JINA_KEY ? 800 : 3500);
    }
    j.detail_status = (j.description_text || '').length >= 80 ? 'ok' : 'failed';
  } catch (e) {
    j.detail_status = 'failed';
    j.detail_error = String(e.message || e).slice(0, 120);
    if (/429|999/.test(j.detail_error) && j.detail.mode === 'linkedin') liBlocked = true;   // throttled: defer the rest
  }
}
return items.map(j => ({ json: j }));

// Job Radar v2 | Gate B (Code, run once for all items). Input: "Detail Fetch".
// Deterministic gates on the description, before any LLM call:
//   experience_years  "3+ years of experience", "minimum two (2) years", "Experience: 2+ yrs" ...
//   language          required non-English language, banned phrases, or a JD written in German/French
//   visa_negative / work_authorization / visa_unknown   (hybrid and on-site need a visa signal)
//   remote_region_desc  "US only", "must reside in the UK" ...
//   opportunity_blocked  commission only, revenue share, pay per meeting, partnership offers
// Rule: drop only on clear evidence. Ambiguous cases go to the LLM, which re-checks (gate C).
const L = $('Load Config').first().json;
const C = L.config;
const items = $input.all().map(i => i.json).filter(j => j.url);
if (!items.length) return [{ json: { __empty: true } }];

const esc = s => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const phraseRe = terms => (terms && terms.length)
  ? new RegExp('(?:^|[^a-z0-9])(' + terms.map(t => esc(String(t).toLowerCase()).replace(/\s+/g, '\\s+')).join('|') + ')(?=$|[^a-z0-9])', 'i') : null;
const hit = (re, text) => { if (!re) return ''; const m = String(text || '').match(re); return m ? m[1] : ''; };

// ---- experience: minimum years required (lenient: the smallest stated minimum wins) ----
const WORDS = { zero: 0, one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10 };
const N = '(\\d{1,2}(?:\\.\\d)?|zero|one|two|three|four|five|six|seven|eight|nine|ten)';
const YEARS_RE = new RegExp('(up to |less than |under |at least |a minimum of |minimum of |minimum |min\\.? |over |more than )?' + N +
  '(?:\\s*\\(\\d{1,2}\\))?\\s*(\\+|plus| or more)?\\s*(?:(?:-|to|or)\\s*' + N + '\\s*\\+?\\s*)?(years?|yrs?|months?)\\b', 'g');
const toNum = s => (s in WORDS ? WORDS[s] : Number(s));
function minYears(text) {
  const t = ' ' + String(text || '').toLowerCase().replace(/[‐-―]/g, '-').replace(/\s+/g, ' ') + ' ';
  const zeroHint = /\b(no (prior |previous |professional )?(work )?experience (is )?(required|needed|necessary)|new grads?|recent graduates?|0 years)\b/.test(t);
  let best = null, evidence = '';
  YEARS_RE.lastIndex = 0;
  let m;
  while ((m = YEARS_RE.exec(t)) !== null) {
    const after = t.slice(YEARS_RE.lastIndex, YEARS_RE.lastIndex + 80);
    const before = t.slice(Math.max(0, m.index - 50), m.index);
    const expAfter = /^\s*(?:'s|’s)?\s*(?:of\s+)?(?:[a-z0-9/&+.,'’()-]+\s+){0,6}?(?:experience|exp\b|work history|track record)/.test(after);
    const expBefore = /(?:experience|exp)\s*(?:required|level|needed)?\s*(?:[:\-–]|of)?\s*$/.test(before);
    if (!expAfter && !expBefore) continue;
    if (/\b(combined|collective|total team)\b/.test(after.slice(0, 40))) continue;
    if (/\b(founded|since|ago|in business|history of|established|for over)\b[^.]{0,25}$/.test(before)) continue;
    if (/^[^.]{0,60}\b(nice to have|is a plus|a plus|bonus|preferred|ideally|advantage)\b/.test(after)) continue;
    let lo = toNum(m[2]);
    if (/^month/.test(m[5])) lo = lo / 12;
    if (/up to|less than|under/.test(m[1] || '')) lo = 0;
    if (!Number.isFinite(lo)) continue;
    if (best === null || lo < best) { best = lo; evidence = t.slice(Math.max(0, m.index - 20), YEARS_RE.lastIndex + 45).trim(); }
  }
  return { min: best, evidence: evidence.slice(0, 160), zeroHint };
}

// ---- language ----
const blocked = (C.languages.blocked || []).map(s => s.toLowerCase());
const langReqRe = blocked.length ? new RegExp(
  '\\b(?:(?:fluent|fluency|native|proficient|proficiency|business[- ]level|professional|excellent|strong|working)\\s+(?:in\\s+|command of\\s+)?(' + blocked.map(esc).join('|') +
  ')|(' + blocked.map(esc).join('|') + ')\\s*(?:\\((?:c1|c2|b2)\\)|c1|c2|b2)?\\s*(?:language\\s+)?(?:skills\\s+)?(?:is\\s+|are\\s+)?(?:required|mandatory|essential|a must|must[- ]have|needed))\\b', 'i') : null;
const bannedRe = phraseRe(C.languages.banned_phrases);
// Pay models and offers that are not paid work: commission only, revenue share, pay per meeting, partnerships.
const offerRe = phraseRe((C.opportunity || {}).block_phrases);
const STOP = {
  german: [' und ', ' der ', ' die ', ' das ', ' wir ', ' für ', ' mit ', ' sie ', ' ist ', ' nicht ', ' auf '],
  french: [' et ', ' les ', ' des ', ' nous ', ' pour ', ' vous ', ' une ', ' dans ', ' sur ', ' avec '],
  dutch: [' en ', ' het ', ' een ', ' wij ', ' voor ', ' met ', ' van ', ' je ', ' zijn '],
  spanish: [' y ', ' los ', ' las ', ' para ', ' con ', ' una ', ' del ', ' nuestro ', ' somos ']
};
const EN = [' and ', ' the ', ' you ', ' we ', ' for ', ' with ', ' our ', ' to ', ' of ', ' is '];
const count = (t, words) => words.reduce((n, w) => n + t.split(w).length - 1, 0);
function jdLanguage(text) {
  const t = ' ' + String(text || '').toLowerCase().replace(/\s+/g, ' ').slice(0, 2500) + ' ';
  const en = count(t, EN);
  let best = 'english', bestN = en;
  for (const [lang, words] of Object.entries(STOP)) { const n = count(t, words); if (n > bestN * 1.3 && n >= 8) { best = lang; bestN = n; } }
  return best;
}

// ---- visa and region ----
const posRe = phraseRe(C.visa.positive_terms);
const negRe = phraseRe(C.visa.negative_terms);
const authRe = phraseRe(C.visa.work_auth_terms);
const descBlockRe = phraseRe(C.work_modes.remote.desc_block);
const sponsors = (C.visa.known_sponsors || []).map(s => s.toLowerCase().replace(/[^a-z0-9]/g, '')).filter(Boolean);
const isSponsor = company => { const c = String(company || '').toLowerCase().replace(/[^a-z0-9]/g, ''); return !!c && sponsors.some(s => c === s || c.startsWith(s)); };
const modeOf = t => /\bhybrid\b/i.test(t) ? 'hybrid' : /\b(fully remote|remote[- ]first|100% remote|work from anywhere|remote position|remote role)\b/i.test(t) ? 'remote'
  : /\b(on[- ]?site|in[- ]office|office[- ]based|onsite)\b/i.test(t) ? 'onsite' : 'unknown';

const maxYears = Number(C.experience.max_years_required) || 0;

function gate(j) {
  if (j.detail_status === 'deferred') return ['deferred', 'detail_deferred', ''];
  if (j.detail_status === 'failed') return ['retry', 'detail_retry', j.detail_error || ''];
  const desc = String(j.description_text || '');
  if (desc.trim().length < 50) return ['drop', 'no_description', desc.length + ' chars'];
  const low = desc.toLowerCase();
  const offer = hit(offerRe, String(j.title || '').toLowerCase() + ' \n ' + low);
  if (offer) return ['drop', 'opportunity_blocked', offer];

  if (j.work_mode === 'unknown') {
    const m = modeOf(desc.slice(0, 2000));
    if (m !== 'unknown') { j.work_mode = m; j.work_mode_from = 'description'; }
  }
  const wm = C.work_modes;
  if ((j.work_mode === 'hybrid' || j.work_mode === 'onsite') && !wm[j.work_mode].enabled) return ['drop', 'mode_disabled', j.work_mode];
  if (j.work_mode === 'remote' && !wm.remote.enabled) return ['drop', 'mode_disabled', 'remote'];

  const ex = minYears(desc);
  j.regex_min_years = ex.min;
  j.regex_evidence = ex.evidence;
  if (ex.min !== null && ex.min >= maxYears + 1) return ['drop', 'experience_years', ex.evidence];

  if (C.languages.detect_jd_language) {
    const lang = jdLanguage(desc);
    j.jd_language = lang;
    if (lang !== 'english' && blocked.includes(lang)) return ['drop', 'language', 'description written in ' + lang];
  }
  const lr = desc.match(langReqRe || /$^/);
  if (lr) return ['drop', 'language', lr[0].trim().slice(0, 80)];
  const banned = hit(bannedRe, low);
  if (banned) return ['drop', 'banned_phrase', banned];

  const neg = hit(negRe, low);
  const auth = hit(authRe, low);
  const pos = hit(posRe, low);
  j.visa_signal = neg ? 'negative' : auth ? 'work_auth' : (pos || j.visa_flag === true || isSponsor(j.company)) ? 'positive' : 'unknown';
  j.visa_evidence = neg || auth || pos || (j.visa_flag === true ? 'source flag' : isSponsor(j.company) ? 'known sponsor' : '');

  if (j.work_mode === 'remote') {
    if (auth) return ['drop', 'work_authorization', auth];   // specific phrases only, e.g. "authorized to work in the us"
    const region = hit(descBlockRe, low);
    if (region) return ['drop', 'remote_region_desc', region];
  } else if (j.work_mode === 'hybrid' || j.work_mode === 'onsite') {
    if (wm[j.work_mode].require_visa) {
      if (neg) return ['drop', 'visa_negative', neg];
      if (auth) return ['drop', 'work_authorization', auth];
      if (j.visa_signal !== 'positive' && C.visa.unknown_policy === 'drop') return ['drop', 'visa_unknown', 'no sponsorship or relocation signal'];
    }
  }
  return ['pass', '', ''];
}

return items.map(j => {
  const [g, reason, detail] = gate(j);
  return { json: Object.assign(j, { gate_b: g, gate_b_reason: reason, gate_b_detail: String(detail || '').slice(0, 300) }) };
});

// Job Radar v2 | Rank & Slice (Code, run once for all items). Input: "Gate B".
// Ranks gate B survivors with a cheap heuristic and sends at most llm.slice_cap to the LLM, with at
// most llm.max_per_source from one source (so one noisy board cannot eat the budget). The rest is
// recorded as skipped_cap and comes back next run while still inside the freshness window.
const L = $('Load Config').first().json;
const C = L.config;
const pass = $input.all().map(i => i.json).filter(j => j.url && j.gate_b === 'pass');
if (!pass.length) return [{ json: { __empty: true } }];

const esc = s => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const skillRes = (C.search.skills || []).map(s => new RegExp('(?:^|[^a-z0-9])' + esc(String(s).toLowerCase()) + '(?=$|[^a-z0-9])', 'i'));
const junior = (() => { try { return new RegExp(C.search.title_junior_regex, 'i'); } catch (e) { return /$^/; } })();
for (const j of pass) {
  const text = j.title + ' ' + j.description_text;
  const skills = skillRes.filter(re => re.test(text)).length;
  const ageDays = (Date.now() - new Date(j.posted_date).getTime()) / 86400000;
  j.heuristic_score = Math.min(skills, 10)
    + (/\b(gtm|automation|revops|n8n|clay|hubspot|crm|workflow)\b/i.test(j.title) ? 4 : 0)
    + (junior.test(j.title) ? 3 : 0)
    + (j.regex_min_years === 0 || j.regex_min_years === null ? 1 : 0)
    + (j.visa_signal === 'positive' ? 2 : 0)
    + (ageDays <= 2 ? 2 : ageDays <= 4 ? 1 : 0)
    + (j.retry ? 1 : 0);
}
pass.sort((a, b) => b.heuristic_score - a.heuristic_score);
const cap = Math.max(1, Number(C.llm.slice_cap) || 25);
const perSource = Math.max(1, Number(C.llm.max_per_source) || cap);
const used = {};
const slice = [];
for (const j of pass) {
  if (slice.length >= cap) break;
  if ((used[j.source] || 0) >= perSource) continue;
  used[j.source] = (used[j.source] || 0) + 1;
  slice.push(j);
}
return slice.map(j => ({ json: j }));

// Job Radar v2 | Build Writes (Code, run once for all items). Input: "Gate & Score".
// Collects every stage change of this run into ONE payload for jr_record_postings():
// gate B drops, detail retries and deferrals, slice overflow, LLM outcomes and the new matches.
const safeAll = name => { try { return $(name).all().map(i => i.json); } catch (e) { return []; } };
const gateB = safeAll('Gate B').filter(j => j.url && j.posting_id);
const sliced = new Set(safeAll('Rank & Slice').filter(j => j.url).map(j => j.url));
const scored = $input.all().map(i => i.json).filter(j => j.url);

const updates = [];
for (const j of gateB) {
  if (j.gate_b === 'drop') updates.push({ posting_id: j.posting_id, stage: 'dropped_b', reason: j.gate_b_reason, detail: j.gate_b_detail });
  else if (j.gate_b === 'retry') updates.push({ posting_id: j.posting_id, stage: 'queued', reason: 'detail_retry', detail: j.gate_b_detail, attempt: true });
  else if (j.gate_b === 'deferred') updates.push({ posting_id: j.posting_id, stage: 'queued', reason: 'detail_deferred' });
  else if (j.gate_b === 'pass' && !sliced.has(j.url)) updates.push({ posting_id: j.posting_id, stage: 'skipped_cap', reason: 'slice_cap' });
}
const matches = [];
for (const r of scored) {
  if (r.outcome === 'matched') matches.push(r.match);
  else if (r.outcome === 'below_score') updates.push({ posting_id: r.posting_id, stage: 'below_score', reason: r.reason, detail: r.detail, final_score: r.final_score });
  else if (r.outcome === 'dropped_llm') updates.push({ posting_id: r.posting_id, stage: 'dropped_llm', reason: r.reason, detail: r.detail });
  else if (r.outcome === 'llm_failed') updates.push({ posting_id: r.posting_id, stage: 'llm_failed', reason: r.reason, detail: r.detail });
  else if (r.outcome === 'deferred') updates.push({ posting_id: r.posting_id, stage: 'skipped_cap', reason: 'llm_time_budget' });
}
const L = $('Load Config').first().json;
return [{ json: { run_id: L.run_id, rev: L.rev, payload: { updates, matches }, counts: { updates: updates.length, matches: matches.length } } }];

// Job Radar v2 | RevOps Roles Error (Code, run once for all items). Input: error output #1 of "RevOps Roles".
// The HTTP node runs with "continue (using error output)". Before this node the error branch was not
// connected, so a 429 made the source vanish with errors = 0. It now becomes a {source, __error} marker that
// Normalize passes through and Run Stats / v_jr_source_health count.
const SOURCE = 'revopsroles';
const j = $input.first().json || {};
const e = j.error || {};
const d = j.details || {};
const status = e.status || e.httpCode || '';
const msg = [status ? 'HTTP ' + status : '', d.message || e.message || 'request failed'].filter(Boolean).join(': ');
return [{ json: { source: SOURCE, __error: SOURCE + ': ' + String(msg).slice(0, 180) } }];
